(function(){
'use strict';
const G=PatternGenetics,S=PatternSumo,B=PatternBeetles,A=PatternLabApp,$=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let match=null,paused=false,acc=0,lastFrame=0,playback=1,participants=null,connection=null,pollTimer=null,pollBusy=false,serverOffset=0,seenMatch=0,lastLogged=null;
const descriptions={tracking:'How accurately a beetle aims at a moving opponent.',reaction:'How often it reconsiders its direction.',focus:'How reliably it keeps attending to its opponent.',pushDrive:'The tendency to approach and push instead of exploring.',wander:'The tendency to choose a wandering path. It can interrupt a promising push.',turnRate:'How quickly it turns. High mass and very fast running make sharp turns harder.',tactics:'Game intelligence: sometimes seeks a side approach instead of meeting the opponent head-on.',edgeSense:'How often it notices the boundary and turns inward.',brace:'How firmly it supports a head-on push.',lateralBalance:'Resistance to being moved by a side push.',grip:'How effectively feet transfer force to the table.',endurance:'How slowly pushing effort drains its available energy.',recovery:'How quickly it regains energy while not pushing; also helps resist rear pushes.',mass:'Heavier beetles resist movement, but take longer to accelerate and turn.',acceleration:'How quickly it builds up walking speed.',centerDrive:'How strongly exploratory paths favor the middle.',curiosity:'How often wandering changes into an approach.',sociality:'How much it approaches nearby beetles in the breeder tank.',caution:'How much it helps edge awareness override a risky path.',persistence:'How likely it is to keep pursuing an ongoing push.'};
function display(b,fallback='Beetle'){return b?.name?b.name+' · '+b.id:b?.id||fallback;}
function download(filename,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function picked(){const s=A.getState();return [s.beetles[$('sumo-a').value],s.beetles[$('sumo-b').value]];}
function players(){return connection&&participants?participants:picked();}
function refresh(){const s=A.getState();$('sumo-section').hidden=s.settings.allowSumo===false;$('specimen-red').hidden=s.settings.allowSumo===false;$('specimen-blue').hidden=s.settings.allowSumo===false;
 for(const [id,index] of [['sumo-a',0],['sumo-b',1]]){const select=$(id),old=select.value;select.innerHTML=Object.values(s.beetles).map(b=>`<option value="${b.id}">${esc(display(b))} · Gen ${b.lineageGeneration}${s.collection.includes(b.id)?' · kept':''}</option>`).join('');select.value=s.beetles[old]?old:Object.keys(s.beetles)[index]||'B1';select.disabled=!!connection;}
 if(connection)connectionUI();else if(!match)preview();
}
function preview(){const [a,b]=picked();if(!a||!b)return;participants=[a,b];$('fighter-a').innerHTML=B.draw(a,'arena-a');$('fighter-b').innerHTML=B.draw(b,'arena-b');$('fighter-a').style.transform='translate(-50%,-50%) rotate(90deg)';$('fighter-b').style.transform='translate(-50%,-50%) rotate(-90deg)';$('fighter-a').style.left='28%';$('fighter-b').style.left='72%';for(const id of ['fighter-a','fighter-b'])$(id).style.top='50%';$('sumo-ring').classList.add('resting');}
function newMatch(list,seed,shared=false){A.cool(false);participants=list.map(G.clone);match=S.create(participants[0],participants[1],seed);match.shared=shared;paused=false;acc=0;lastLogged=null;$('fighter-a').innerHTML=B.draw(participants[0],'arena-a');$('fighter-b').innerHTML=B.draw(participants[1],'arena-b');$('sumo-pause').disabled=shared;$('sumo-pause').textContent='Pause match';$('sumo-ring').classList.remove('resting');$('ring-countdown').hidden=true;$('sumo-ring').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('sumo-result').textContent=shared?'Shared match — both screens use the same decision rolls.':'A fresh match. Watch the approach and the pushing angles.';}
function drawMatch(){if(!match)return;for(const [i,id] of ['fighter-a','fighter-b'].entries()){const f=match.fighters[i];$(id).style.left=(50+f.x/480*100)+'%';$(id).style.top=(50+f.y/480*100)+'%';$(id).style.transform=`translate(-50%,-50%) rotate(${f.heading+Math.PI/2}rad)`;$(i?'blue-behavior':'red-behavior').textContent=(i?'Blue: ':'Red: ')+f.mode;}
 $('sumo-clock').textContent=Math.floor(match.time/60)+':'+String(Math.floor(match.time%60)).padStart(2,'0');
 if(match.done){$('sumo-ring').classList.add('resting');$('sumo-pause').disabled=true;const winner=match.winner===null?'A draw':(match.winner===0?'Red':'Blue')+' wins';const side=match.events.filter(e=>e.side==='side').length,rear=match.events.filter(e=>e.side==='rear').length,wandering=match.fighters.map(f=>Math.round(f.wanderingTime));$('sumo-result').textContent=winner+' · '+match.reason+'. Side contacts: '+side+'; rear contacts: '+rear+'. Wandering: red '+wandering[0]+'s, blue '+wandering[1]+'s.';
  const key=match.seed+'-'+match.tick+'-'+(connection?.code||'local');if(lastLogged!==key){lastLogged=key;const state=A.getState();state.matchHistory=state.matchHistory||[];if(!state.matchHistory.some(r=>r.seed===match.seed&&r.fighters.map(f=>f.genomeFingerprint).join('|')===match.fighters.map(f=>G.checksum(JSON.stringify(f.beetle.genome)+f.beetle.developmentSeed)).join('|')))state.matchHistory.push({...S.record(match),participants:match.fighters.map(f=>G.packet(f.beetle)),source:match.shared?'shared':'local',recordedAt:new Date().toISOString()});state.matchHistory=state.matchHistory.slice(-100);A.save();}
  if(connection?.role==='host')$('room-start').disabled=false;
 }
}
function animate(now){const dt=Math.min(.15,(now-lastFrame)/1000||0);lastFrame=now;
 if(match&&!match.done){
  if(match.shared&&connection?.room?.startedAt){const elapsed=(Date.now()-serverOffset-Date.parse(connection.room.startedAt))/1000;$('ring-countdown').hidden=elapsed>=0;$('ring-countdown').textContent=elapsed<0?String(Math.ceil(-elapsed)):'';const target=Math.min(match.maxSeconds,Math.max(0,elapsed));while(!match.done&&match.time+1/120<target)S.step(match);}
  else if(!paused&&!document.hidden){acc+=dt*playback;let count=0;while(acc>=1/60&&count++<100){S.step(match);acc-=1/60;if(match.done)break;}}
  drawMatch();
 }
 requestAnimationFrame(animate);
}
function traitCard(b,index){const p=G.phenotype(b);return `<div class="compare-beetle"><h3>${index?'Blue corner':'Red corner'} · ${esc(display(b))}</h3>${B.draw(b,'compare'+index)}<p>${G.antennaNames[p.antenna]} · ${G.legNames[p.leg]}<br>${p.visibleLayers} visible pattern ${p.visibleLayers===1?'color':'colors'}</p>${A.getState().settings.showStats?Object.keys(descriptions).map(k=>`<div class="trait-meter"><span>${G.byKey[k].label}</span><meter min="0" max="1" value="${p[k]}">${Math.round(p[k]*100)}%</meter><b>${Math.round(p[k]*100)}</b></div>`).join(''):'<p class="hint">Exact measurements are hidden in this class. Observe their walking, approaches and contests to learn about their traits.</p>'}</div>`;}
function compare(){const list=players();if(list.some(b=>!b))return;$('comparison-content').innerHTML=list.map(traitCard).join('');$('comparison').showModal();A.cool(false);}
function allele(a,l){return l.type==='number'?a.toFixed(3):l.type==='color'?'RGB '+a.rgb.join(', ')+'; expression '+a.expression.toFixed(3):a.value+'; expression '+a.expression.toFixed(3);}
function exportBeetle(documentMode){const b=A.getState().beetles[A.getSelected()];if(!b)return;const packet=G.packet(b),json=JSON.stringify(packet,null,2),base='Pattern-Lab-'+b.id;
 if(!documentMode){download(base+'.json',json);A.toast('Beetle JSON exported. Import beetle file adds it to any compatible tank.');return;}
 const p=G.phenotype(b),html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(display(b))} — Beetle record</title><style>body{font:15px/1.6 system-ui;color:#254b3e;max-width:960px;margin:40px auto;padding:25px}h1,h2{font-family:Georgia}svg{float:right;width:270px;height:340px;background:#edf1df;border-radius:20px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:7px;border:1px solid #dae1d2;text-align:left}h2{clear:both;padding-top:20px}.leg-swing{animation:none}button{padding:10px 16px}@media print{button{display:none}table{break-inside:auto}tr{break-inside:avoid}body{margin:0}}</style><h1>${esc(display(b))}</h1><p>Leaf &amp; Lineage · Pattern Lab v2 · Portable beetle record</p>${B.draw(b,'document')}<p>Lineage generation ${b.lineageGeneration}<br>Parents: ${b.parents.map(esc).join(', ')||'Founder or externally recorded ancestry'}<br>${G.antennaNames[p.antenna]} antennae · ${G.legNames[p.leg]}<br>${p.visibleLayers} visible pattern colors · speed ${p.speed} · strength ${p.strengthIndex}/100</p><p>This HTML document embeds the full genetic packet. Use <strong>Import beetle file</strong> to re-upload this document or its JSON counterpart. Printing a PDF creates a readable report; use HTML or JSON to restore the beetle.</p><button onclick="window.print()">Print / save as PDF</button><h2>Both copies of every gene</h2>${G.chromosomes.map(c=>`<h3>Chromosome ${c.id}</h3><table><thead><tr><th>Trait</th><th>Copy 1</th><th>Copy 2</th></tr></thead><tbody>${c.loci.map(l=>{const cp=G.copies(b,l.key);return `<tr><td>${l.label}</td><td>${esc(allele(cp[0],l))}</td><td>${esc(allele(cp[1],l))}</td></tr>`;}).join('')}</tbody></table>`).join('')}<p>Invented teaching genetics and game traits, not measured real-species biology. Development seed ${b.developmentSeed}; genotype fingerprint ${G.checksum(JSON.stringify(b.genome)+b.developmentSeed)}.</p><script type="application/json" id="pattern-beetle-data">${json.replace(/</g,'\\u003c')}</script></html>`;
 download(base+'.html',html,'text/html');A.toast('Printable beetle document exported, with embedded data for re-upload.');
}
function parseFile(text){const trimmed=text.trim();if(trimmed.startsWith('{'))return G.validatePacket(JSON.parse(trimmed));const found=text.match(/<script type="application\/json" id="pattern-beetle-data">([\s\S]*?)<\/script>/);if(!found)throw Error('Choose a beetle JSON or an exported beetle HTML document.');return G.validatePacket(JSON.parse(found[1]));}
function family(){const s=A.getState(),id=A.getSelected();if(!s.beetles[id])return;function branch(key,depth,path){const b=s.beetles[key];if(!b)return '<span>External ancestry</span>';if(path.includes(key))return '<span>Repeated ancestor</span>';return `<div class="tree-node"><button data-tree="${b.id}">${esc(display(b))}<small>Generation ${b.lineageGeneration}</small></button>${b.provenance?'<small>Imported · source '+esc(b.provenance.sourceId)+'</small>':''}${depth<3&&b.parents.length?'<div class="tree-parents">'+b.parents.map(p=>branch(p,depth+1,[...path,key])).join('')+'</div>':''}</div>`;}$('family-tree-content').innerHTML=branch(id,0,[]);$('family-tree').showModal();}
function log(){const rows=A.getState().matchHistory||[];$('match-log-content').innerHTML=rows.slice().reverse().map((m,i)=>`<article class="history-item"><strong>${esc(m.winner===null?'Draw':m.winner===0?'Red won':'Blue won')} · ${m.seconds}s</strong><p>${esc(m.reason)} · ${m.source==='shared'?'Shared table':'Local table'}<br>${m.fighters.map((f,j)=>(j?'Blue':'Red')+': '+esc(f.name||f.id)+' · wandering '+f.wanderingSeconds+'s · side pushes '+f.sidePushes).join('<br>')}</p><button data-replay="${rows.length-1-i}">Replay recorded match</button></article>`).join('')||'<p>No completed matches yet. Make a prediction before your first contest.</p>';$('match-log').showModal();}
function secureToken(){const bytes=crypto.getRandomValues(new Uint8Array(32));return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function request(action,payload){const cfg=globalThis.PatternSharingConfig;if(!cfg?.url)throw Error('Online rooms are not configured. Local sumo and beetle files still work.');const response=await fetch(cfg.url,{method:'POST',headers:{'Content-Type':'application/json',apikey:cfg.publishableKey},body:JSON.stringify({action,...payload}),signal:AbortSignal.timeout(15000)});let data;try{data=await response.json();}catch{throw Error('The sharing service did not respond. Try again shortly.');}if(!response.ok)throw Error(data.error||'Could not connect to that table.');return data;}
function connectionUI(){const active=!!connection;$('sumo-a').disabled=active;$('sumo-b').disabled=active;$('sumo-start').disabled=active;$('room-create').disabled=active;$('room-join').disabled=active;$('room-code-box').hidden=!active;$('room-leave').hidden=!active;$('room-start').hidden=!active||connection.role!=='host';$('sumo-speed').disabled=active;if(active){$('room-code').value=connection.code.slice(0,4)+'-'+connection.code.slice(4);$('sumo-a').selectedOptions[0].textContent='Shared host beetle · red corner';$('sumo-b').selectedOptions[0].textContent=connection.room?.guest?'Shared visitor beetle · blue corner':'Waiting for a visitor';$('sumo-speed').value='1';playback=1;}}
function persistConnection(){try{if(connection)sessionStorage.setItem('pattern-sumo-connection',JSON.stringify({code:connection.code,token:connection.token,role:connection.role}));else sessionStorage.removeItem('pattern-sumo-connection');}catch{}}
function applyRoom(room){if(!connection)return;connection.room=room;serverOffset=Date.now()-Date.parse(room.serverNow);participants=[G.validatePacket(room.host).beetle,room.guest?G.validatePacket(room.guest).beetle:null];
 $('room-status').textContent=room.guest?(connection.role==='host'?'A visitor’s beetle has arrived. Start the shared match.':'Your beetle is on the blue side. Waiting for the host to start.'):'Code ready. Waiting for a second screen to send a beetle.';$('room-start').disabled=!room.guest;
 if(room.guest&&room.matchNumber>seenMatch&&room.startedAt){seenMatch=room.matchNumber;newMatch(participants,room.seed,true);$('room-start').disabled=true;$('room-status').textContent='Shared match '+room.matchNumber+' · both screens replay the same physics.';}
 if(match?.shared&&!match.done)$('room-start').disabled=true;
 if(room.matchNumber>0)$('room-status').textContent=match?.done?'Shared match '+room.matchNumber+' finished. The host can start a rematch.':'Shared match '+room.matchNumber+' · both screens replay the same physics.';
 connectionUI();
 if(!match){$('fighter-a').innerHTML=B.draw(participants[0],'shared-a');$('fighter-b').innerHTML=participants[1]?B.draw(participants[1],'shared-b'):'';for(const [i,id] of ['fighter-a','fighter-b'].entries()){$(id).style.left=(i?72:28)+'%';$(id).style.top='50%';$(id).style.transform='translate(-50%,-50%) rotate('+(i?-90:90)+'deg)';}$('sumo-ring').classList.add('resting');}
}
async function poll(){if(!connection||pollBusy||document.hidden)return;pollBusy=true;try{const data=await request('read',{code:connection.code,token:connection.token});applyRoom(data.room);}catch(e){$('room-status').textContent=e.message;if(/unavailable|expired/.test(e.message)){clearInterval(pollTimer);connection=null;persistConnection();connectionUI();}}finally{pollBusy=false;}}
function beginPolling(){clearInterval(pollTimer);pollTimer=setInterval(poll,2000);persistConnection();connectionUI();}
function online(action){return async()=>{if(A.isBlocked())return;const beetle=picked()[0];if(!beetle)return;const button=$(action==='create'?'room-create':'room-join');button.disabled=true;$('room-status').textContent=action==='create'?'Creating your room code…':'Sending your beetle…';try{const token=secureToken(),code=$('room-join-code').value;const data=await request(action,{code,token,beetle:G.packet(beetle,{anonymous:true})});connection={code:data.room.code,token,role:action==='create'?'host':'guest',room:data.room};seenMatch=0;match=null;applyRoom(data.room);beginPolling();A.toast(action==='create'?'Room code created. Share it with one classmate.':'Beetle sent to your classmate’s table.');}catch(e){$('room-status').textContent=e.message;button.disabled=false;}};}
$('sumo-start').onclick=()=>{if(connection||A.isBlocked())return;newMatch(picked(),crypto.getRandomValues(new Uint32Array(1))[0]);A.cool(false);};
$('sumo-pause').onclick=()=>{if(match?.shared)return;paused=!paused;$('sumo-pause').textContent=paused?'Resume match':'Pause match';$('sumo-ring').classList.toggle('resting',paused);};
$('sumo-speed').onchange=()=>{playback=Number($('sumo-speed').value);};for(const id of ['sumo-a','sumo-b'])$(id).onchange=()=>{if(match&&!match.done){A.toast('These choices apply to the next match.');return;}match=null;preview();};
$('compare-open').onclick=compare;$('sumo-guide-open').onclick=()=>{$('sumo-trait-guide').innerHTML=Object.entries(descriptions).map(([k,d])=>'<h3>'+G.byKey[k].label+'</h3><p>'+d+'</p>').join('');$('sumo-guide').showModal();};
$('export-beetle-json').onclick=()=>exportBeetle(false);$('export-beetle-doc').onclick=()=>exportBeetle(true);$('family-tree-open').onclick=family;
for(const [button,corner] of [['specimen-red','sumo-a'],['specimen-blue','sumo-b']])$(button).onclick=()=>{if(connection){A.toast('Leave the shared table before changing local corners.');return;}$(corner).value=A.getSelected();match=null;preview();$('inspector').close();$('sumo-section').scrollIntoView({block:'start',behavior:'smooth'});};
$('family-tree-content').onclick=e=>{const b=e.target.closest('[data-tree]');if(b)A.inspect(b.dataset.tree);};
$('import-beetle').onclick=()=>$('beetle-file').click();$('beetle-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1024*1024)throw Error('Choose a single-beetle file under 1 MB. Use Open tank file for a whole experiment.');const b=A.addBeetle(parseFile(await f.text()));$('sumo-a').value=b.id;A.toast('Imported '+b.id+' with its exact genes and appearance.');A.inspect(b.id);}catch(error){A.toast(error.message);}e.target.value='';};
$('match-log-open').onclick=log;$('match-json').onclick=()=>download('Pattern-Lab-sumo-matches.json',JSON.stringify({model:'SUMO2',matches:A.getState().matchHistory||[]},null,2));
$('match-log-content').onclick=e=>{const b=e.target.closest('[data-replay]');if(!b)return;if(connection){A.toast('Leave the shared table before replaying a local record.');return;}const record=A.getState().matchHistory[Number(b.dataset.replay)];if(!record?.participants)return;newMatch(record.participants.map(p=>G.validatePacket(p).beetle),record.seed);$('match-log').close();};
$('room-create').onclick=online('create');$('room-join').onclick=online('join');$('room-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('room-code').value);A.toast('Room code copied.');}catch{$('room-code').select();A.toast('Select and copy the code.');}};
$('room-start').onclick=async()=>{if(connection?.role!=='host')return;$('room-start').disabled=true;try{const data=await request('start',{code:connection.code,token:connection.token});applyRoom(data.room);}catch(e){$('room-status').textContent=e.message;$('room-start').disabled=false;}};
$('room-leave').onclick=async()=>{const old=connection;connection=null;clearInterval(pollTimer);persistConnection();connectionUI();seenMatch=0;refresh();if(match?.shared){match=null;preview();}if(old?.role==='host')try{await request('close',{code:old.code,token:old.token});}catch{}$('room-status').textContent='You left the shared table. Your beetles are still safe in your tank.';};
window.addEventListener('pattern-state',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&connection)poll();});
refresh();requestAnimationFrame(animate);
try{const previous=JSON.parse(sessionStorage.getItem('pattern-sumo-connection')||'null');if(previous&&A.getState().settings.allowSumo!==false&&!A.isBlocked()&&/^[A-Z2-9]{8}$/.test(previous.code)&&/^[A-Za-z0-9_-]{43}$/.test(previous.token)&&['host','guest'].includes(previous.role)){connection=previous;beginPolling();poll();}}catch{}
})();
